 * @hidden N
 */
scwin.krxpage_pagenavigator_110_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_ViewTreasuryStockReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil20300.krxpage_pagenavigator_110_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ViewTreasuryStock
 * @description View Treasury Stock 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewTreasuryStock = async function () {
    const sbmOptions = {
        id: "tx_fn_ViewTreasuryStock",
        method: "post",
        action: "/company/treasuryStock.do",
        ref: "dma_ViewTreasuryStockReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

