///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name viewTreasuryStock
 * @description view Treasury Stock 처리
 * @param {String} _flag _flag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewTreasuryStock = async function (_flag) {
    let methodVal = "";
    switch (_flag) {
        case 1:
        methodVal = "searchTreasuryStockDeclaration";
        break;
        case 2:
        methodVal = "searchTreasuryStockApplication";
        break;
        case 3:
        methodVal = "searchTreasuryStockTrading";
        break;
        case 4:
        methodVal = "searchTreasuryStockTradingDetail";
        break;
    }
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('method', methodVal);
    await scwin.tx_fn_ViewTreasuryStock();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('excelTpCd', "N");
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('method', "searchTreasuryStockDeclaration");
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('excelTpCd', "Y");
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('method', "searchTreasuryStockDeclaration");
    await scwin.tx_fn_Excel();
};

/**
 * @method
 * @name setSearchPeriod
 * @description 조회 기간 버튼 — 오늘을 종료일로, 구분에 따라 시작일을 계산해 넣고 조회(as-is 공통 fn_ClickPeriod)
 * @param {*} type 1 1주 · 2 1개월 · 3 3개월 · 4 6개월 · 5 1년 · 6 2년 · 7 3년
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSearchPeriod = async function (type) {
    const edate = $c.date.getServerDateTime("yyyyMMdd");
    const offsets = { 1: ["addDate", -7], 2: ["addMonth", -1], 3: ["addMonth", -3], 4: ["addMonth", -6], 5: ["addYear", -1], 6: ["addYear", -2], 7: ["addYear", -3] };
    const o = offsets[Number(type)];
    const sdate = o ? $c.date[o[0]](edate, o[1]) : edate;
    await scwin.setPeriodDates(sdate, edate);
};

/**
 * @method
 * @name setPeriodDates
 * @description 조회 기간(시작일·종료일)을 달력에 넣고 바로 조회(as-is 공통 fn_SetPeriod → fn_Search)
 * @param {*} sdate 시작일(yyyyMMdd)
 * @param {*} edate 종료일(yyyyMMdd)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPeriodDates = async function (sdate, edate) {
    $c.util.getComponent("cal_sdate").setValue(sdate);
    $c.util.getComponent("cal_edate").setValue(edate);
    await scwin.search();
};
